// bundle_client.js — pre-build step run BEFORE pkg.
//
// Concatenates the client-side JS modules into a single _player_bundle.js
// which gets shipped as a pkg asset. The HTTP /player.js handler just
// reads that one file at runtime.
//
// Why: pkg bytecodes any .js it can statically discover (matched by the
// 'scripts' glob OR reached via require()). Bytecoded files return
// empty content from fs.readFileSync. Listing individual client-side
// files in 'assets' did not override the bytecoding. A single arbitrary
// .js file we generate at build time and never require() avoids both
// discovery paths.

'use strict';
const fs = require('fs');
const path = require('path');

const modules = [
  'shared/safe_dom.js',
  'player_core.js',
  'mse_engine.js',
  'tunnel_settings.js',
  'cinema_player.js',
  'search_ui.js',
  // v8.0.16: playback_state.js exposes window.startSmartMonitor — must load
  // BEFORE smart_play.js so monitorForFile's thin wrapper can find it.
  'playback_state.js',
  'smart_play.js',
  'poster_hero.js',
  'init.js',
];

const root = path.resolve(__dirname, '..');
const out = path.join(root, '_player_bundle.js');

let combined = '/* eSE client-side bundle. Auto-generated by tools/bundle_client.js — do not edit. */\n';
let bytes = 0;
let missing = 0;
for (const mod of modules) {
  const p = path.join(root, mod);
  if (fs.existsSync(p)) {
    const content = fs.readFileSync(p, 'utf8');
    combined += '\n// ==== ' + mod + ' (' + content.length + ' bytes) ====\n' + content + '\n';
    bytes += content.length;
  } else {
    console.warn('  [bundle_client] missing:', mod);
    missing++;
  }
}
fs.writeFileSync(out, combined);
console.log('  [bundle_client] wrote ' + out + ' — ' + modules.length + ' modules, ' + missing + ' missing, ' + bytes + ' source bytes, ' + combined.length + ' bundle bytes');
